    this.burst({ dur: 0.9, type: 'highpass', freq: 3200, q: 0.5, vol: 0.13 });
    this.tone({ freq: 500, to: 1500, dur: 0.6, vol: 0.12, type: 'sawtooth', filter: 2200, vibrato: [16, 40] });
  }

