import * as THREE from 'three';
import { spriteTexture, type SpriteKind } from './textures';

interface Particle {
  sprite: THREE.Sprite;
  mat: THREE.SpriteMaterial;
  vel: THREE.Vector3;
  age: number;
  life: number;
  gravity: number;
  drag: number;
  size0: number;
  size1: number;
  spin: number;
  wobble: number;
  wobbleSpeed: number;
  phase: number;
  peak: number;
  active: boolean;
}

export interface EmitOpts {
  kind: SpriteKind;
  pos: THREE.Vector3;
  vel?: THREE.Vector3;
  color?: THREE.ColorRepresentation;
  size?: number;
  sizeEnd?: number;
  life?: number;
  gravity?: number;
  drag?: number;
  spin?: number;
  wobble?: number;
  peak?: number;
  depthTest?: boolean;
}

const POOL = 260;
const tmp = new THREE.Vector3();

export class Particles {
  readonly group = new THREE.Group();
  private pool: Particle[] = [];
  private cursor = 0;

  constructor() {
    for (let i = 0; i < POOL; i++) {
      const mat = new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0 });
      const sprite = new THREE.Sprite(mat);
      sprite.visible = false;
      sprite.renderOrder = 20;
      this.group.add(sprite);
      this.pool.push({
        sprite,
        mat,
        vel: new THREE.Vector3(),
        age: 0,
        life: 1,
        gravity: 0,
        drag: 0,
        size0: 0.2,
        size1: 0.2,
        spin: 0,
        wobble: 0,
        wobbleSpeed: 0,
        phase: 0,
        peak: 1,
        active: false,
      });
    }
  }

  emit(o: EmitOpts) {
    let p: Particle | undefined;
    for (let i = 0; i < POOL; i++) {
      const c = this.pool[(this.cursor + i) % POOL];
      if (!c.active) {
        p = c;
        this.cursor = (this.cursor + i + 1) % POOL;
        break;
      }
    }
    if (!p) {
      p = this.pool[this.cursor];
      this.cursor = (this.cursor + 1) % POOL;
    }
