+] as const;
+type PoseKey = (typeof POSE_KEYS)[number];
+type Pose = Record<PoseKey, number>;
+
+const zeroPose = (): Pose => Object.fromEntries(POSE_KEYS.map((k) => [k, 0])) as Pose;
+
+const RATES: Partial<Record<PoseKey, number>> = {
+  bodyY: 14,
+  squash: 18,
+  lean: 7,
+  roll: 10,
+  headYaw: 8,
+  headPitch: 9,
+  headRoll: 8,
+  mouth: 18,
+  lid: 22,
+  happy: 14,
+  eyeX: 16,
+  eyeY: 16,
+  smile: 9,
+  blush: 3,
+  puff: 16,
+  legFold: 3.2,
+  wide: 14,
+  tailAmp: 5,
