+      pos.needsUpdate = true;
+      this.fireflyMat.size = 0.24 + 0.12 * Math.sin(this.time * 3);
+    }
+
+    // Butterflies
+    const day = 1 - n;
+    this.butterflies.forEach((b, i) => {
+      const t = this.time * 0.35 + b.seed;
