import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import { Cowdie } from './Cowdie';
import { Environment, ISLAND_RADIUS } from './Environment';
import { Particles } from './Particles';
import { Overlay } from './Overlay';
import { foodCrumbColor, foodThumbnails, makeFood } from './Foods';
import { ballTexture } from './textures';
import { bus } from '../game/bus';
import { FOOD_BY_ID, STUFFED_AT, type FoodId } from '../game/config';
import { useGame, type GameState, type Mode } from '../game/store';
import { getMood, levelInfo } from '../game/logic';
import { sfx } from '../audio/sfx';

const rand = (a: number, b: number) => a + Math.random() * (b - a);
const pick = <T,>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];
const smoothstep = (a: number, b: number, x: number) => {
  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

const WALK_BOUNDS = { minX: -4.2, maxX: 4.2, minZ: -2.4, maxZ: 3.2 };

interface Held {
  id: FoodId;
  mesh: THREE.Group;
  pointerId: number;
  startX: number;
  startY: number;
  clientX: number;
  clientY: number;
  t0: number;
  target: THREE.Vector3;
  refused: boolean;
}

interface Flying {
  id: FoodId;
  mesh: THREE.Group;
  from: THREE.Vector3;
  ctrl: THREE.Vector3;
  t: number;
  dur: number;
}

interface GroundFood {
  id: FoodId;
  mesh: THREE.Group;
  vel: THREE.Vector3;
  resting: boolean;
  age: number;
  claimed: boolean;
}

interface PoopObj {
  group: THREE.Group;
  t: number;
  stinkT: number;
  removing: number;
}

interface Ball {
  mesh: THREE.Mesh;
  pos: THREE.Vector3;
  vel: THREE.Vector3;
  radius: number;
  lastKick: number;
  lastBounce: number;
  idle: number;
  scale: number;
  kicks: number;
}

interface Sud {
  mesh: THREE.Mesh;
  t: number;
  target: number;
}

type PointerMode = 'none' | 'pet' | 'orbit' | 'scrub' | 'throw';

const LINES = {
