export class Overlay {
  readonly el: HTMLDivElement;
  private bubble: HTMLDivElement;
  private body: HTMLDivElement;
  private bubbleText: HTMLSpanElement;
  private bubbleIcon: HTMLImageElement;
  private hideTimer = 0;
  private visible = false;
  private anchorX = 0;
  private anchorY = 0;
  private lastText = '';
  private lastAt = 0;

  constructor(container: HTMLElement) {
    this.el = document.createElement('div');
    this.el.className = 'world-overlay';
    this.bubble = document.createElement('div');
    this.bubble.className = 'bubble';
    this.bubble.setAttribute('aria-hidden', 'true');
    this.bubbleIcon = document.createElement('img');
    this.bubbleIcon.className = 'bubble-icon';
    this.bubbleIcon.alt = '';
    this.bubbleText = document.createElement('span');
    this.body = document.createElement('div');
    this.body.className = 'bubble-body';
    this.body.append(this.bubbleIcon, this.bubbleText);
    this.bubble.append(this.body);
    this.el.append(this.bubble);
    container.append(this.el);
  }

import * as THREE from 'three';
import { bodyTexture, headTexture, shadowTexture } from './textures';
import { Particles } from './Particles';
import { buildAccessory } from './Accessories';
import { sfx } from '../audio/sfx';
import type { AccessoryId } from '../game/config';
import type { Mood } from '../game/logic';

const POSE_KEYS = [
  'bodyY',
  'squash',
  'lean',
  'roll',
  'headYaw',
  'headPitch',
  'headRoll',
  'mouth',
  'smile',
  'lid',
  'happy',
  'eyeX',
  'eyeY',
  'earL',
  'earR',
  'tailAmp',
  'tailSpeed',
  'blush',
  'puff',
  'brow',
  'browRaise',
  'tongue',
  'legFold',
  'wide',
  'red',
] as const;
type PoseKey = (typeof POSE_KEYS)[number];
type Pose = Record<PoseKey, number>;

const zeroPose = (): Pose => Object.fromEntries(POSE_KEYS.map((k) => [k, 0])) as Pose;

