+
+.meter.low .meter-fill {
+  background: linear-gradient(180deg, #ff8a95, #ff3f56);
+  animation: throb 0.9s ease-in-out infinite;
+}
+
+.meter.low .meter-icon {
+  background: #ff4058;
+  animation: throb 0.9s ease-in-out infinite;
+}
+
+.top-right {
+  grid-column: 3;
+  justify-self: end;
+  display: flex;
+  gap: 10px;
+  pointer-events: none;
+}
+
+.round-btn {
+  pointer-events: auto;
+  width: 48px;
+  height: 48px;
+  border-radius: 50%;
+  border: 2px solid #fff;
+  background: rgba(255, 255, 255, 0.9);
+  color: var(--ink);
+  display: grid;
+  place-items: center;
+  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.16), 0 10px 20px rgba(59, 42, 78, 0.16);
+  transition: transform 0.12s, box-shadow 0.12s, background 0.2s;
+}
+
+.round-btn:hover {
+  transform: translateY(-2px);
+}
+
+.round-btn:active,
+.round-btn[aria-pressed='true'] {
+  transform: translateY(2px);
+  box-shadow: 0 1px 0 rgba(59, 42, 78, 0.16);
+}
+
+.round-btn[aria-pressed='true'] {
+  background: #fff3c4;
+}
+
+/* ------------------------------------------------------------- bottom bar */
+
+.hud-bottom {
+  position: absolute;
+  left: 0;
+  right: 0;
+  bottom: 0;
+  padding: 0 14px max(16px, env(safe-area-inset-bottom));
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 12px;
+  pointer-events: none;
+}
+
+.dock {
+  display: flex;
+  gap: 10px;
+  padding: 10px;
+  border-radius: 30px;
+}
+
+.dock-btn {
+  --c: #ff8a5b;
+  position: relative;
+  width: 92px;
+  padding: 10px 6px 9px;
+  border: 0;
+  border-radius: 21px;
+  background: linear-gradient(180deg, color-mix(in srgb, var(--c) 78%, #fff) 0%, var(--c) 70%);
+  color: #fff;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 3px;
+  font-weight: 600;
+  font-size: 15px;
+  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.18);
+  box-shadow: 0 6px 0 color-mix(in srgb, var(--c) 60%, #2c1b45), 0 12px 18px color-mix(in srgb, var(--c) 35%, transparent);
+  transition: transform 0.12s, box-shadow 0.12s, filter 0.2s;
+}
+
+.dock-btn:hover {
+  transform: translateY(-3px);
+  filter: brightness(1.05);
+}
+
+.dock-btn:active,
+.dock-btn[aria-pressed='true'] {
+  transform: translateY(4px);
+  box-shadow: 0 2px 0 color-mix(in srgb, var(--c) 60%, #2c1b45);
+}
+
+.dock-btn.dim {
+  filter: saturate(0.35) brightness(1.05);
+  opacity: 0.75;
+}
+
+.dock-icon {
+  display: grid;
+  place-items: center;
+  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, 0.15));
+}
+
+.dock-btn kbd {
+  position: absolute;
+  top: 5px;
+  right: 7px;
+  font: inherit;
+  font-size: 10px;
+  font-weight: 700;
+  opacity: 0.75;
+  background: rgba(0, 0, 0, 0.16);
+  border-radius: 6px;
+  padding: 1px 5px;
+}
+
+@media (hover: none) {
+  .dock-btn kbd {
+    display: none;
+  }
+}
+
+.tray {
+  width: min(660px, 100%);
+  padding: 12px;
+  animation: rise 0.28s cubic-bezier(0.3, 1.4, 0.5, 1);
+}
+
+.tray-cards {
+  display: flex;
+  gap: 10px;
+  justify-content: center;
+  overflow-x: auto;
+  padding: 4px 4px 8px;
+  scrollbar-width: none;
+}
+
+.tray-cards::-webkit-scrollbar {
+  display: none;
+}
+
+.tray-title {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 0 4px 6px;
+  font-size: 17px;
+}
+
+.tray-hint {
+  margin: 0;
+  text-align: center;
+  font-size: 13.5px;
+  font-weight: 500;
+  color: var(--ink-soft);
+  padding: 0 8px;
+}
+
+.food-card,
+.acc-card {
+  position: relative;
+  flex: 0 0 auto;
+  width: 104px;
+  padding: 8px 6px 9px;
+  border: 2px solid #fff;
+  border-radius: 20px;
+  background: linear-gradient(180deg, #fff, #fff7ea);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 1px;
+  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.13), 0 8px 16px rgba(59, 42, 78, 0.1);
+  transition: transform 0.14s cubic-bezier(0.3, 1.6, 0.5, 1), box-shadow 0.14s, opacity 0.2s;
+  touch-action: none;
+}
+
+.acc-card {
+  touch-action: manipulation;
+}
+
+.food-card:hover,
+.acc-card:not(:disabled):hover {
+  transform: translateY(-4px) rotate(-1.5deg);
+}
+
+.food-card:active {
+  transform: scale(0.96);
+}
+
+.food-card img {
+  width: 68px;
+  height: 68px;
+  object-fit: contain;
+  pointer-events: none;
+  margin: -4px 0 -2px;
+  filter: drop-shadow(0 6px 5px rgba(59, 42, 78, 0.22));
+}
+
+.food-card.is-full,
+.food-card.is-busy {
+  opacity: 0.6;
+}
+
+.food-name {
+  font-weight: 600;
+  font-size: 15px;
+}
+
+.food-stats {
+  font-size: 12px;
+  color: var(--ink-soft);
+  font-weight: 500;
+}
+
+.food-stats b {
+  color: #ff7440;
+  font-weight: 700;
+}
+
+.fav-badge {
+  position: absolute;
+  top: 6px;
+  right: 6px;
+  width: 22px;
+  height: 22px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  background: #ff5c8a;
+  color: #fff;
+  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.15);
+}
+
+.fav-badge.on {
+  background: #3dc27c;
+}
+
+.acc-icon {
+  width: 56px;
+  height: 56px;
+  border-radius: 18px;
+  display: grid;
+  place-items: center;
+  margin: 2px 0 4px;
+  background: linear-gradient(180deg, #ffe8f0, #ffd4e3);
+  color: #d5487a;
+}
+
+.acc-card.locked {
+  opacity: 0.6;
+}
+
+.acc-card.locked .acc-icon {
+  background: #ece7f5;
+  color: #8a7ea3;
+}
+
+.acc-card.active {
+  border-color: #3dc27c;
+  background: linear-gradient(180deg, #f2fff7, #dcf9e8);
+}
+
+.mini-btn {
+  width: 30px;
+  height: 30px;
+  border-radius: 50%;
+  border: 0;
+  background: rgba(59, 42, 78, 0.1);
+  display: grid;
+  place-items: center;
+}
+
+.text-btn {
+  border: 2px solid #fff;
+  background: #fff;
+  border-radius: 999px;
+  padding: 8px 16px;
+  font-weight: 600;
+  font-size: 14px;
+  box-shadow: 0 3px 0 rgba(59, 42, 78, 0.16);
+}
+
+.text-btn:active {
+  transform: translateY(2px);
+  box-shadow: 0 1px 0 rgba(59, 42, 78, 0.16);
+}
+
+.text-btn.danger {
+  background: #ff5c6e;
+  border-color: #ff5c6e;
+  color: #fff;
+}
+
+.hint {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 14px;
+  padding: 12px 16px;
+}
+
+.hint-text {
+  display: flex;
+  flex-direction: column;
+  gap: 3px;
+  font-size: 14px;
+  min-width: 0;
+  flex: 1;
+}
+
+.hint-text strong {
+  font-size: 17px;
+}
+
+.hint-text span {
+  color: var(--ink-soft);
+  font-weight: 500;
+}
+
+.progress {
+  height: 12px;
+  border-radius: 99px;
+  background: rgba(59, 42, 78, 0.13);
+  overflow: hidden;
+  margin-top: 4px;
+}
+
+.progress > div {
+  height: 100%;
+  border-radius: 99px;
+  background: linear-gradient(180deg, #8fdcff, #2fb1f5);
+  transition: width 0.25s;
+}
+
+.progress.energy > div {
+  background: linear-gradient(180deg, #ffe07a, #ffbf1f);
+}
+
+.facts {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 8px;
+  margin: 0 0 12px;
+}
+
+.facts div {
+  background: #fff;
+  border-radius: 16px;
+  padding: 8px 6px;
+  text-align: center;
+  box-shadow: 0 3px 0 rgba(59, 42, 78, 0.1);
+}
+
+.facts dt {
+  font-size: 12px;
+  color: var(--ink-soft);
+  font-weight: 500;
+}
+
+.facts dd {
+  margin: 2px 0 0;
+  font-weight: 700;
+  font-size: 15px;
+}
+
+.menu-actions {
+  display: flex;
+  gap: 10px;
+  justify-content: center;
+  flex-wrap: wrap;
+  margin-bottom: 10px;
+}
+
+/* ------------------------------------------------------------- overlay */
+
+.world-overlay {
+  position: absolute;
+  inset: 0;
+  pointer-events: none;
+  overflow: hidden;
+}
+
+.bubble {
+  position: absolute;
+  left: 0;
+  top: 0;
+  z-index: 3;
+  pointer-events: none;
+  will-change: transform;
+}
+
+.bubble-body {
+  position: relative;
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  padding: 9px 16px;
+  max-width: min(76vw, 320px);
+  text-align: center;
+  font-weight: 600;
+  font-size: 17px;
+  line-height: 1.2;
+  color: var(--ink);
+  background: #fff;
+  border-radius: 22px;
+  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.14), 0 12px 26px rgba(59, 42, 78, 0.22);
+  opacity: 0;
+  transform-origin: 50% 100%;
+  margin-bottom: 12px;
+}
+
+.bubble-body::after {
+  content: '';
+  position: absolute;
+  left: 50%;
+  bottom: -9px;
+  width: 18px;
+  height: 18px;
+  background: #fff;
+  transform: translateX(-50%) rotate(45deg);
+  border-radius: 0 0 6px 0;
+}
+
+.bubble-body.thought {
+  background: #f6f2ff;
+}
+
+.bubble-body.thought::after {
+  background: #f6f2ff;
+  width: 14px;
+  height: 14px;
+  border-radius: 50%;
+  bottom: -14px;
+  box-shadow: 8px 8px 0 -3px #f6f2ff;
+}
+
+.bubble-body.show {
+  opacity: 1;
+  animation: pop 0.32s cubic-bezier(0.3, 1.7, 0.5, 1);
+}
+
+.bubble-icon {
+  width: 34px;
+  height: 34px;
+  object-fit: contain;
+}
+
+.float {
+  position: absolute;
+  transform: translate(-50%, -50%);
+  font-weight: 700;
+  font-size: 22px;
+  color: #fff;
+  paint-order: stroke fill;
+  -webkit-text-stroke: 6px var(--fc, #5b4a8a);
+  opacity: 0;
+  white-space: nowrap;
+  animation: floatup 1.7s ease-out forwards;
+  pointer-events: none;
+}
+
+.float-belly {
+  --fc: #e2622f;
+}
+.float-joy {
+  --fc: #d63a6c;
+}
+.float-energy {
+  --fc: #cf9500;
+}
+.float-fresh {
+  --fc: #1a94d8;
+}
+.float-xp {
+  --fc: #5b4a8a;
+  font-size: 18px;
+}
+
+/* ------------------------------------------------------------- toasts */
+
+.toasts {
+  position: absolute;
+  left: 50%;
+  top: calc(var(--top-h) + 10px);
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 8px;
+  pointer-events: none;
+  width: min(92vw, 460px);
+  z-index: 5;
+}
+
+.toast {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  padding: 10px 18px;
+  background: #fff;
+  border-radius: 20px;
+  font-size: 15px;
+  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.13), 0 14px 28px rgba(59, 42, 78, 0.22);
+  animation: drop 0.4s cubic-bezier(0.3, 1.5, 0.5, 1);
+}
+
+.toast strong {
+  display: block;
+  font-size: 17px;
+}
+
+.toast span {
+  color: var(--ink-soft);
+  font-weight: 500;
+}
+
+.toast-level {
+  background: linear-gradient(135deg, #fff6c9, #ffe0ee);
+  border: 2px solid #fff;
+}
+
+.toast-icon {
+  width: 42px;
+  height: 42px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  background: #ffbf1f;
+  color: #fff !important;
+  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.14);
+  flex: none;
+}
+
+/* ------------------------------------------------------------- animation */
+
+@keyframes throb {
+  50% {
+    filter: brightness(1.18);
+    transform: scale(1.03);
+  }
+}
+
+@keyframes rise {
+  from {
+    opacity: 0;
+    transform: translateY(20px) scale(0.96);
+  }
+}
+
+@keyframes drop {
+  from {
+    opacity: 0;
+    transform: translateY(-16px) scale(0.94);
+  }
+}
+
+@keyframes pop {
+  0% {
+    transform: scale(0.4);
+    opacity: 0;
+  }
+  100% {
+    transform: scale(1);
+    opacity: 1;
+  }
+}
+
+@keyframes floatup {
+  0% {
+    opacity: 0;
+    transform: translate(-50%, 0) scale(0.6);
+  }
+  15% {
+    opacity: 1;
+    transform: translate(-50%, -14px) scale(1.15);
+  }
+  30% {
+    transform: translate(-50%, -22px) scale(1);
+  }
+  100% {
+    opacity: 0;
+    transform: translate(-50%, -84px) scale(1);
+  }
+}
+
+/* ------------------------------------------------------------- responsive */
+
+@media (max-width: 1080px) {
+  .hud-top {
+    grid-template-columns: 1fr auto;
+    row-gap: 10px;
+  }
+  .stats {
+    grid-column: 1 / -1;
+    grid-row: 2;
+    grid-template-columns: repeat(4, 1fr);
+    gap: 14px;
+  }
+  .top-right {
+    grid-column: 2;
+    grid-row: 1;
+  }
+}
+
+@media (max-width: 620px) {
+  .hud-top {
+    padding: max(10px, env(safe-area-inset-top)) 10px 0;
+    gap: 8px;
+  }
+  .title {
+    font-size: 21px;
+    -webkit-text-stroke-width: 6px;
+  }
+  .top-left {
+    gap: 6px;
+  }
+  .pet-card {
+    padding: 4px 12px 4px 5px;
+  }
+  .level-ring {
+    width: 40px;
+    height: 40px;
+  }
+  .level-ring svg {
+    width: 40px;
+    height: 40px;
+  }
+  .level-ring span {
+    font-size: 16px;
+  }
+  .pet-name {
+    font-size: 15px;
+  }
+  .pet-xp {
+    display: none;
+  }
+  .round-btn {
+    width: 40px;
+    height: 40px;
+  }
+  .top-right {
+    gap: 7px;
+  }
+  .stats {
+    grid-template-columns: 1fr 1fr;
+    gap: 9px 12px;
+    padding: 9px 12px;
+    border-radius: 20px;
+  }
+  .meter-icon {
+    width: 26px;
+    height: 26px;
+  }
+  .meter-icon svg {
+    width: 15px;
+    height: 15px;
+  }
+  .meter-label {
+    font-size: 12px;
+    margin-bottom: 3px;
+  }
+  .meter-bar {
+    height: 10px;
+  }
+  .dock {
+    gap: 7px;
+    padding: 8px;
+    border-radius: 26px;
+  }
+  .dock-btn {
+    width: 72px;
+    font-size: 13px;
+    padding: 8px 4px 7px;
+  }
+  .dock-icon svg {
+    width: 26px;
+    height: 26px;
+  }
+  .food-card,
+  .acc-card {
+    width: 92px;
+  }
+  .food-card img {
+    width: 58px;
+    height: 58px;
+  }
+  .tray {
+    padding: 10px 8px;
+  }
+  .tray-cards {
+    justify-content: flex-start;
+  }
+  .facts {
+    grid-template-columns: repeat(2, 1fr);
+  }
+  .bubble-body {
+    font-size: 15px;
+    padding: 8px 13px;
+  }
+}
+
+@media (max-height: 560px) and (orientation: landscape) {
+  .title {
+    font-size: 22px;
+  }
+  .pet-card {
+    display: none;
+  }
+  .stats {
+    padding: 7px 12px;
+  }
+  .dock-btn {
+    width: 74px;
+    padding: 6px 4px 6px;
+  }
+  .dock-btn kbd {
+    display: none;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *,
+  *::before,
+  *::after {
+    animation-duration: 0.01ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.01ms !important;
+  }
+}

success.afterFullFileContent:
:root {
  --ink: #3b2a4e;
  --ink-soft: #6f5f86;
  --panel: rgba(255, 255, 255, 0.8);
  --panel-edge: rgba(255, 255, 255, 0.9);
  --shadow: 0 5px 0 rgba(59, 42, 78, 0.1), 0 16px 34px rgba(59, 42, 78, 0.18);
  --top-h: 120px;
  font-family: 'Fredoka Variable', 'Fredoka', ui-rounded, system-ui, sans-serif;
  color: var(--ink);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: #8fd3ff;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
  box-shadow: 0 0 0 6px #7b6cf0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

.stage {
  position: absolute;
  inset: 0;
}

.scene-canvas {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.scene-error {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  gap: 8px;
  text-align: center;
  padding: 24px;
  font-size: 18px;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 46%, transparent 55%, rgba(40, 20, 80, 0.22) 100%);
}

/* ------------------------------------------------------------- panels */

.panel {
  pointer-events: auto;
  background: var(--panel);
  border: 2px solid var(--panel-edge);
  border-radius: 24px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px) saturate(1.4);
  -webkit-backdrop-filter: blur(14px) saturate(1.4);
}

/* ------------------------------------------------------------- top bar */

.hud-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: max(14px, env(safe-area-inset-top)) 18px 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 14px;
  pointer-events: none;
}

.top-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}

.title {
  margin: 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.01em;
  color: #fff;
  paint-order: stroke fill;
  -webkit-text-stroke: 7px #5b4a8a;
  text-shadow: 0 4px 0 #5b4a8a, 0 10px 22px rgba(59, 42, 78, 0.28);
  pointer-events: none;
  white-space: nowrap;
}

.pet-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 16px 7px 8px;
  border-radius: 999px;
}

.level-ring {
  position: relative;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  flex: none;
}

.level-ring svg {
  position: absolute;
  inset: 0;
}

.level-ring span {
  font-weight: 700;
  font-size: 19px;
  color: var(--ink);
}

.ring-bg {
  fill: #fff;
  stroke: rgba(59, 42, 78, 0.12);
  stroke-width: 5;
}

.ring-fg {
  fill: none;
  stroke: #ff5c8a;
  stroke-width: 5;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.6s cubic-bezier(0.3, 1.2, 0.5, 1);
}

.pet-meta {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.pet-name {
  font-size: 17px;
}

.pet-stage,
.pet-xp {
  font-size: 12.5px;
  color: var(--ink-soft);
  font-weight: 500;
}

.stats {
  grid-column: 2;
  display: grid;
  grid-template-columns: repeat(4, 148px);
  gap: 16px;
  padding: 12px 18px;
}

.meter {
  --c: #ff8a5b;
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.meter-icon {
  flex: none;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--c);
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.16), 0 2px 6px color-mix(in srgb, var(--c) 45%, transparent);
}

.meter-body {
  flex: 1;
  min-width: 0;
}

.meter-label {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
  margin-bottom: 5px;
}

.meter-value {
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.meter-bar {
  height: 12px;
  border-radius: 99px;
  background: rgba(59, 42, 78, 0.13);
  overflow: hidden;
  box-shadow: inset 0 2px 3px rgba(59, 42, 78, 0.12);
}

.meter-fill {
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--c) 70%, #fff) 0%, var(--c) 60%);
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.12);
  transition: width 0.6s cubic-bezier(0.3, 1.3, 0.5, 1), background 0.3s;
}

.meter.low .meter-fill {
  background: linear-gradient(180deg, #ff8a95, #ff3f56);
  animation: throb 0.9s ease-in-out infinite;
}

.meter.low .meter-icon {
  background: #ff4058;
  animation: throb 0.9s ease-in-out infinite;
}

.top-right {
  grid-column: 3;
  justify-self: end;
  display: flex;
  gap: 10px;
  pointer-events: none;
}

.round-btn {
  pointer-events: auto;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid #fff;
  background: rgba(255, 255, 255, 0.9);
  color: var(--ink);
  display: grid;
  place-items: center;
  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.16), 0 10px 20px rgba(59, 42, 78, 0.16);
  transition: transform 0.12s, box-shadow 0.12s, background 0.2s;
}

.round-btn:hover {
  transform: translateY(-2px);
}

.round-btn:active,
.round-btn[aria-pressed='true'] {
  transform: translateY(2px);
  box-shadow: 0 1px 0 rgba(59, 42, 78, 0.16);
}

.round-btn[aria-pressed='true'] {
  background: #fff3c4;
}

/* ------------------------------------------------------------- bottom bar */

.hud-bottom {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 0 14px max(16px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  pointer-events: none;
}

.dock {
  display: flex;
  gap: 10px;
  padding: 10px;
  border-radius: 30px;
}

.dock-btn {
  --c: #ff8a5b;
  position: relative;
  width: 92px;
  padding: 10px 6px 9px;
  border: 0;
  border-radius: 21px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--c) 78%, #fff) 0%, var(--c) 70%);
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  font-weight: 600;
  font-size: 15px;
  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.18);
  box-shadow: 0 6px 0 color-mix(in srgb, var(--c) 60%, #2c1b45), 0 12px 18px color-mix(in srgb, var(--c) 35%, transparent);
  transition: transform 0.12s, box-shadow 0.12s, filter 0.2s;
}

.dock-btn:hover {
  transform: translateY(-3px);
  filter: brightness(1.05);
}

.dock-btn:active,
.dock-btn[aria-pressed='true'] {
  transform: translateY(4px);
  box-shadow: 0 2px 0 color-mix(in srgb, var(--c) 60%, #2c1b45);
}

.dock-btn.dim {
  filter: saturate(0.35) brightness(1.05);
  opacity: 0.75;
}

.dock-icon {
  display: grid;
  place-items: center;
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, 0.15));
}

.dock-btn kbd {
  position: absolute;
  top: 5px;
  right: 7px;
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  opacity: 0.75;
  background: rgba(0, 0, 0, 0.16);
  border-radius: 6px;
  padding: 1px 5px;
}

@media (hover: none) {
  .dock-btn kbd {
    display: none;
  }
}

.tray {
  width: min(660px, 100%);
  padding: 12px;
  animation: rise 0.28s cubic-bezier(0.3, 1.4, 0.5, 1);
}

.tray-cards {
  display: flex;
  gap: 10px;
  justify-content: center;
  overflow-x: auto;
  padding: 4px 4px 8px;
  scrollbar-width: none;
}

.tray-cards::-webkit-scrollbar {
  display: none;
}

.tray-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px 6px;
  font-size: 17px;
}

.tray-hint {
  margin: 0;
  text-align: center;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--ink-soft);
  padding: 0 8px;
}

.food-card,
.acc-card {
  position: relative;
  flex: 0 0 auto;
  width: 104px;
  padding: 8px 6px 9px;
  border: 2px solid #fff;
  border-radius: 20px;
  background: linear-gradient(180deg, #fff, #fff7ea);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.13), 0 8px 16px rgba(59, 42, 78, 0.1);
  transition: transform 0.14s cubic-bezier(0.3, 1.6, 0.5, 1), box-shadow 0.14s, opacity 0.2s;
  touch-action: none;
}

.acc-card {
  touch-action: manipulation;
}

.food-card:hover,
.acc-card:not(:disabled):hover {
  transform: translateY(-4px) rotate(-1.5deg);
}

.food-card:active {
  transform: scale(0.96);
}

.food-card img {
  width: 68px;
  height: 68px;
  object-fit: contain;
  pointer-events: none;
  margin: -4px 0 -2px;
  filter: drop-shadow(0 6px 5px rgba(59, 42, 78, 0.22));
}

.food-card.is-full,
.food-card.is-busy {
  opacity: 0.6;
}

.food-name {
  font-weight: 600;
  font-size: 15px;
}

.food-stats {
  font-size: 12px;
  color: var(--ink-soft);
  font-weight: 500;
}

.food-stats b {
  color: #ff7440;
  font-weight: 700;
}

.fav-badge {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #ff5c8a;
  color: #fff;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.15);
}

.fav-badge.on {
  background: #3dc27c;
}

.acc-icon {
  width: 56px;
  height: 56px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  margin: 2px 0 4px;
  background: linear-gradient(180deg, #ffe8f0, #ffd4e3);
  color: #d5487a;
}

.acc-card.locked {
  opacity: 0.6;
}

.acc-card.locked .acc-icon {
  background: #ece7f5;
  color: #8a7ea3;
}

.acc-card.active {
  border-color: #3dc27c;
  background: linear-gradient(180deg, #f2fff7, #dcf9e8);
}

.mini-btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 0;
  background: rgba(59, 42, 78, 0.1);
  display: grid;
  place-items: center;
}

.text-btn {
  border: 2px solid #fff;
  background: #fff;
  border-radius: 999px;
  padding: 8px 16px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 3px 0 rgba(59, 42, 78, 0.16);
}

.text-btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 rgba(59, 42, 78, 0.16);
}

.text-btn.danger {
  background: #ff5c6e;
  border-color: #ff5c6e;
  color: #fff;
}

.hint {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 16px;
}

.hint-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 14px;
  min-width: 0;
  flex: 1;
}

.hint-text strong {
  font-size: 17px;
}

.hint-text span {
  color: var(--ink-soft);
  font-weight: 500;
}

.progress {
  height: 12px;
  border-radius: 99px;
  background: rgba(59, 42, 78, 0.13);
  overflow: hidden;
  margin-top: 4px;
}

.progress > div {
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(180deg, #8fdcff, #2fb1f5);
  transition: width 0.25s;
}

.progress.energy > div {
  background: linear-gradient(180deg, #ffe07a, #ffbf1f);
}

.facts {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin: 0 0 12px;
}

.facts div {
  background: #fff;
  border-radius: 16px;
  padding: 8px 6px;
  text-align: center;
  box-shadow: 0 3px 0 rgba(59, 42, 78, 0.1);
}

.facts dt {
  font-size: 12px;
  color: var(--ink-soft);
  font-weight: 500;
}

.facts dd {
  margin: 2px 0 0;
  font-weight: 700;
  font-size: 15px;
}

.menu-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

/* ------------------------------------------------------------- overlay */

.world-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.bubble {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 3;
  pointer-events: none;
  will-change: transform;
}

.bubble-body {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 16px;
  max-width: min(76vw, 320px);
  text-align: center;
  font-weight: 600;
  font-size: 17px;
  line-height: 1.2;
  color: var(--ink);
  background: #fff;
  border-radius: 22px;
  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.14), 0 12px 26px rgba(59, 42, 78, 0.22);
  opacity: 0;
  transform-origin: 50% 100%;
  margin-bottom: 12px;
}

.bubble-body::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -9px;
  width: 18px;
  height: 18px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 0 0 6px 0;
}

.bubble-body.thought {
  background: #f6f2ff;
}

.bubble-body.thought::after {
  background: #f6f2ff;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  bottom: -14px;
  box-shadow: 8px 8px 0 -3px #f6f2ff;
}

.bubble-body.show {
  opacity: 1;
  animation: pop 0.32s cubic-bezier(0.3, 1.7, 0.5, 1);
}

.bubble-icon {
  width: 34px;
  height: 34px;
  object-fit: contain;
}

.float {
  position: absolute;
  transform: translate(-50%, -50%);
  font-weight: 700;
  font-size: 22px;
  color: #fff;
  paint-order: stroke fill;
  -webkit-text-stroke: 6px var(--fc, #5b4a8a);
  opacity: 0;
  white-space: nowrap;
  animation: floatup 1.7s ease-out forwards;
  pointer-events: none;
}

.float-belly {
  --fc: #e2622f;
}
.float-joy {
  --fc: #d63a6c;
}
.float-energy {
  --fc: #cf9500;
}
.float-fresh {
  --fc: #1a94d8;
}
.float-xp {
  --fc: #5b4a8a;
  font-size: 18px;
}

/* ------------------------------------------------------------- toasts */

.toasts {
  position: absolute;
  left: 50%;
  top: calc(var(--top-h) + 10px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
  width: min(92vw, 460px);
  z-index: 5;
}

.toast {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 18px;
  background: #fff;
  border-radius: 20px;
  font-size: 15px;
  box-shadow: 0 4px 0 rgba(59, 42, 78, 0.13), 0 14px 28px rgba(59, 42, 78, 0.22);
  animation: drop 0.4s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.toast strong {
  display: block;
  font-size: 17px;
}

.toast span {
  color: var(--ink-soft);
  font-weight: 500;
}

.toast-level {
  background: linear-gradient(135deg, #fff6c9, #ffe0ee);
  border: 2px solid #fff;
}

.toast-icon {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #ffbf1f;
  color: #fff !important;
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.14);
  flex: none;
}

/* ------------------------------------------------------------- animation */

@keyframes throb {
  50% {
    filter: brightness(1.18);
    transform: scale(1.03);
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.96);
  }
}

@keyframes drop {
  from {
    opacity: 0;
    transform: translateY(-16px) scale(0.94);
  }
}

@keyframes pop {
  0% {
    transform: scale(0.4);
    opacity: 0;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes floatup {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0.6);
  }
  15% {
    opacity: 1;
    transform: translate(-50%, -14px) scale(1.15);
  }
  30% {
    transform: translate(-50%, -22px) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -84px) scale(1);
  }
}

/* ------------------------------------------------------------- responsive */

@media (max-width: 1080px) {
  .hud-top {
    grid-template-columns: 1fr auto;
    row-gap: 10px;
  }
  .stats {
    grid-column: 1 / -1;
    grid-row: 2;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
  }
  .top-right {
    grid-column: 2;
    grid-row: 1;
  }
}

@media (max-width: 620px) {
  .hud-top {
    padding: max(10px, env(safe-area-inset-top)) 10px 0;
    gap: 8px;
  }
  .title {
    font-size: 21px;
    -webkit-text-stroke-width: 6px;
  }
  .top-left {
    gap: 6px;
  }
  .pet-card {
    padding: 4px 12px 4px 5px;
  }
  .level-ring {
    width: 40px;
    height: 40px;
  }
  .level-ring svg {
    width: 40px;
    height: 40px;
  }
  .level-ring span {
    font-size: 16px;
  }
  .pet-name {
    font-size: 15px;
  }
  .pet-xp {
    display: none;
  }
  .round-btn {
    width: 40px;
    height: 40px;
  }
  .top-right {
    gap: 7px;
  }
  .stats {
    grid-template-columns: 1fr 1fr;
    gap: 9px 12px;
    padding: 9px 12px;
    border-radius: 20px;
  }
  .meter-icon {
    width: 26px;
    height: 26px;
  }
  .meter-icon svg {
    width: 15px;
    height: 15px;
  }
  .meter-label {
    font-size: 12px;
    margin-bottom: 3px;
  }
  .meter-bar {
    height: 10px;
  }
  .dock {
    gap: 7px;
    padding: 8px;
    border-radius: 26px;
  }
  .dock-btn {
    width: 72px;
    font-size: 13px;
    padding: 8px 4px 7px;
  }
  .dock-icon svg {
    width: 26px;
    height: 26px;
  }
  .food-card,
  .acc-card {
    width: 92px;
  }
  .food-card img {
    width: 58px;
    height: 58px;
  }
  .tray {
    padding: 10px 8px;
  }
  .tray-cards {
    justify-content: flex-start;
  }
  .facts {
    grid-template-columns: repeat(2, 1fr);
  }
  .bubble-body {
    font-size: 15px;
    padding: 8px 13px;
  }
}

@media (max-height: 560px) and (orientation: landscape) {
  .title {
    font-size: 22px;
  }
  .pet-card {
    display: none;
  }
  .stats {
    padding: 7px 12px;
  }
  .dock-btn {
    width: 74px;
    padding: 6px 4px 6px;
  }
  .dock-btn kbd {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

