private sleepTimer = -1;
private boopTimes: number[] = [];
private lastMoodSay = 0;
private stuffedSayAt = 0;
private playKickCount = 0;
private hintPoopSay = 0;

private thumbs: Record<FoodId, string>;

constructor(private container: HTMLElement) {
  this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  this.renderer.shadowMap.enabled = true;
  this.renderer.shadowMap.type = THREE.PCFShadowMap;
  this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  this.renderer.toneMappingExposure = 1.02;
  this.canvas = this.renderer.domElement;
  this.canvas.className = 'scene-canvas';
  this.canvas.setAttribute('aria-label', 'Cowdie the virtual cow in a meadow');
  this.canvas.setAttribute('role', 'img');
  container.append(this.canvas);

  this.env = new Environment();
  this.scene.add(this.env.group, this.fx.group);
  this.scene.background = this.env.background;
  this.cowdie = new Cowdie(this.fx);
  this.cowdie.root.position.set(0, 0, 0.5);
  this.scene.add(this.cowdie.root);
  this.overlay = new Overlay(container);
  this.thumbs = foodThumbnails();

  this.ballRing = new THREE.Mesh(
    new THREE.RingGeometry(0.32, 0.46, 40),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false }),
  );
  this.ballRing.rotation.x = -Math.PI / 2;
  this.ballRing.position.y = 0.04;
  this.ballRing.renderOrder = 2;
  this.scene.add(this.ballRing);

  this.sponge = this.makeSponge();
  this.sponge.visible = false;
  this.scene.add(this.sponge);

  this.cowdie.onStep = () => {
    this.fx.puff(this.cowdie.position.clone().setY(0.08), 1, 0xdff5c8, 0.22);
  };

  this.bindEvents();
  this.resizeObs = new ResizeObserver(() => this.resize());
  this.resizeObs.observe(container);
  this.resize();

  const s = useGame.getState();
  this.cowdie.setLevel(levelInfo(s.xp).level, true);
  this.cowdie.setAccessory(s.worn);
  this.cowdie.setSleeping(s.sleeping);
  this.env.snapSleep(s.sleeping ? 1 : 0);
  sfx.setMuted(s.muted);
  this.syncPoops(true);
  if (s.mode === 'play') this.enterMode('play');
  this.lastInteraction = performance.now();

  this.lastFrame = performance.now();
  this.raf = requestAnimationFrame(this.frame);
}

// ------------------------------------------------------------------ setup

private bindEvents() {
  const c = this.canvas;
  const on = (el: HTMLElement | Window, type: string, fn: (e: never) => void, opts?: AddEventListenerOptions) => {
    el.addEventListener(type, fn as unknown as EventListener, opts);
    this.cleanups.push(() => el.removeEventListener(type, fn as unknown as EventListener, opts));
  };
  on(c, 'pointerdown', this.onPointerDown);
  on(window, 'pointermove', this.onPointerMove);
  on(window, 'pointerup', this.onPointerUp);
  on(window, 'pointercancel', this.onPointerUp);
  on(c, 'pointerleave', () => {
    this.ptr.inside = false;
  });
  on(c, 'wheel', this.onWheel, { passive: false });
  on(c, 'contextmenu', (e: Event) => e.preventDefault());

  this.cleanups.push(
    useGame.subscribe((state, prev) => this.onStore(state, prev)),
    bus.on('say', ({ text }) => this.overlay.say(text)),
    bus.on('levelup', ({ level }) => this.onLevelUp(level)),
    bus.on('wake', ({ reason, grumpy }) => this.onWake(reason, grumpy)),
    bus.on('autosleep', () => {
      this.overlay.say('Zzz... I can’t keep my eyes open...', { ms: 3000 });
    }),
  );
}

private resize() {
  const w = Math.max(1, this.container.clientWidth);
  const h = Math.max(1, this.container.clientHeight);
  this.width = w;
  this.height = h;
  this.renderer.setSize(w, h, false);
  const aspect = w / h;
  this.camera.aspect = aspect;
  this.camera.fov = aspect < 0.85 ? 46 : 38;
  const tan = Math.tan(THREE.MathUtils.degToRad(this.camera.fov / 2));
  this.baseDist = aspect < 1.05 ? THREE.MathUtils.clamp(5.6 / (2 * tan * aspect), 8.6, 14) : 8.6;
  this.applyViewOffset();
}

setInsets(top: number, bottom: number) {
  this.insetTop = top;
  this.insetBottom = bottom;
  this.applyViewOffset();
}

private applyViewOffset() {
  const shift = THREE.MathUtils.clamp((this.insetTop - this.insetBottom) / 2, -this.height * 0.2, this.height * 0.25);
  this.camera.setViewOffset(this.width, this.height, 0, -shift, this.width, this.height);
  this.camera.updateProjectionMatrix();
}

private makeSponge() {
  const g = new THREE.Group();
  const top = new THREE.Mesh(new RoundedBoxGeometry(0.72, 0.2, 0.46, 3, 0.08), new THREE.MeshStandardMaterial({ color: 0xffd84a, roughness: 0.85 }));

  this.step(dt);
  this.renderer.render(this.scene, this.camera);
};

step(dt: number) {
  this.time += dt;
  this.tickBrain(dt);
  this.updateFoods(dt);
  this.updateBall(dt);
  this.updatePoops(dt);
  this.updateWash(dt);
  this.cowdie.update(dt);
  this.clampCow();
  this.env.update(dt, useGame.getState().sleeping ? 1 : 0);
  this.fx.update(dt);
  this.updateCamera(dt);

  const top = this.cowdie.topWorld(this.tmp);
  const sc = this.toScreen(top);
  this.overlay.setAnchor(sc.x, Math.max(90, sc.y - 8));
}

private clampCow() {
  const p = this.cowdie.position;
  const r = Math.hypot(p.x, p.z);
  const maxR = ISLAND_RADIUS - 1.5;
  if (r > maxR) {
    p.x *= maxR / r;
    p.z *= maxR / r;
  }
}

private updateCamera(dt: number) {
  this.orbitIdle += dt;
  if (!this.ptr.down && this.orbitIdle > 5) {
    this.camYawT *= 1 - Math.min(1, dt * 0.6);
    this.camPitchT += (0.26 - this.camPitchT) * Math.min(1, dt * 0.6);
    this.zoomT += (1 - this.zoomT) * Math.min(1, dt * 0.5);
  }
  const k = 1 - Math.exp(-6 * dt);
  this.camYaw += (this.camYawT - this.camYaw) * k;
  this.camPitch += (this.camPitchT - this.camPitch) * k;
  this.zoom += (this.zoomT - this.zoom) * k;

  const px = this.ptr.inside ? this.ndc.x : 0;
  const py = this.ptr.inside ? this.ndc.y : 0;
  const yaw = this.camYaw + px * 0.035;
  const pitch = this.camPitch - py * 0.012;
  const dist = this.baseDist * this.zoom;
  this.camTarget.set(0, 1.2, 0.2);
  this.camera.position.set(
    this.camTarget.x + Math.sin(yaw) * Math.cos(pitch) * dist,
    this.camTarget.y + Math.sin(pitch) * dist,
    this.camTarget.z + Math.cos(yaw) * Math.cos(pitch) * dist,
  );
  this.camera.lookAt(this.camTarget);
  this.camera.updateMatrixWorld();
}

// ------------------------------------------------------------------ debug / test hooks

debug() {

import type { ComponentType } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { STAT_META, type StatKey } from '../game/config';
import { levelInfo, stageName } from '../game/logic';
import { useGame } from '../game/store';
import { sfx } from '../audio/sfx';
import { IconBolt, IconDrop, IconFeed, IconHat, IconHeart, IconMenu, IconMute, IconSound } from './icons';

const METER_ICONS: Record<StatKey, ComponentType<{ size?: number }>> = {
  fullness: IconFeed,
  joy: IconHeart,
  energy: IconBolt,
  clean: IconDrop,
};

const METER_COLORS: Record<StatKey, string> = {
  fullness: '#ff8a5b',
  joy: '#ff5c8a',
  energy: '#ffbf1f',
  clean: '#3fb8ff',
};

function Meter({ k, value }: { k: StatKey; value: number }) {
  const Ico = METER_ICONS[k];
  const low = value < 25;
  return (
    <div
      className={`meter${low ? ' low' : ''}`}
      style={{ ['--c' as string]: METER_COLORS[k] }}
      role="meter"
      aria-label={STAT_META[k].label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(value)}
      data-stat={k}
    >
      <span className="meter-icon">
        <Ico size={18} />
      </span>
      <div className="meter-body">
        <div className="meter-label">
          <span>{STAT_META[k].label}</span>
          <span className="meter-value">{Math.round(value)}</span>
        </div>
        <div className="meter-bar">
          <div className="meter-fill" style={{ width: `${Math.max(2, value)}%` }} />
        </div>
      </div>
    </div>
  );
}

function Stats() {
  const s = useGame(useShallow((g) => ({ fullness: g.fullness, joy: g.joy, energy: g.energy, clean: g.clean })));
  return (
    <section className="panel stats" aria-label="Cowdie's needs">
      {(['fullness', 'joy', 'energy', 'clean'] as StatKey[]).map((k) => (
        <Meter key={k} k={k} value={s[k]} />
      ))}
    </section>
  );
}

function PetCard() {
  const xp = useGame((g) => g.xp);
  const sleeping = useGame((g) => g.sleeping);
  const { level, into, need } = levelInfo(xp);
  const pct = Math.min(1, into / need);
  const R = 19;
  const C = 2 * Math.PI * R;
  return (
    <div className="panel pet-card" aria-label={`Cowdie, level ${level}`}>
      <div className="level-ring" data-level={level}>
        <svg viewBox="0 0 48 48" width="48" height="48" aria-hidden="true">
          <circle cx="24" cy="24" r={R} className="ring-bg" />
          <circle
            cx="24"
            cy="24"
            r={R}
            className="ring-fg"
            strokeDasharray={C}
            strokeDashoffset={C * (1 - pct)}
            transform="rotate(-90 24 24)"
          />
        </svg>
        <span>{level}</span>
      </div>
      <div className="pet-meta">
        <strong className="pet-name">Cowdie</strong>
        <span className="pet-stage">
          {stageName(level)}
          {sleeping ? ' · asleep' : ''}
        </span>
        <span className="pet-xp">
          {Math.floor(into)} / {need} XP
        </span>
      </div>
    </div>
  );
}

export function TopBar() {
  const muted = useGame((g) => g.muted);
  const panel = useGame((g) => g.panel);
  const toggleMuted = useGame((g) => g.toggleMuted);
  const togglePanel = useGame((g) => g.togglePanel);
  return (
    <header className="hud-top" data-hud="top">
      <div className="top-left">
        <h1 className="title">Claude Sonnet 5.5</h1>
        <PetCard />
      </div>
      <Stats />
      <div className="top-right">
        <button
          className="round-btn"
          aria-label={muted ? 'Turn sound on' : 'Turn sound off'}
          aria-pressed={!muted}
          onClick={() => {
            toggleMuted();
            window.setTimeout(() => sfx.click(), 30);
          }}
          title={muted ? 'Sound off' : 'Sound on'}
        >
          {muted ? <IconMute /> : <IconSound />}
        </button>
        <button
          className="round-btn"
          aria-label="Wardrobe"
          aria-pressed={panel === 'wardrobe'}
          onClick={() => {
            sfx.click();
            togglePanel('wardrobe');
          }}
          title="Wardrobe"
        >
          <IconHat />
        </button>
        <button
          className="round-btn"
          aria-label="Menu"
          aria-pressed={panel === 'menu'}
          onClick={() => {
            sfx.click();
            togglePanel('menu');
          }}
          title="Menu"
        >
          <IconMenu />
        </button>
      </div>
    </header>
  );
}

