@media (max-width: 1080px) {
  .hud-top {
    grid-template-columns: 1fr auto;
    row-gap: 10px;
  }
  .stats {
    grid-column: 1 / -1;
    grid-row: 2;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
  }
  .top-right {
    grid-column: 2;
    grid-row: 1;
  }
}

@media (max-width: 620px) {
  .hud-top {
    padding: max(10px, env(safe-area-inset-top)) 10px 0;
    gap: 8px;
  }
  .title {
    font-size: 21px;
    -webkit-text-stroke-width: 6px;
  }
  .top-left {
    gap: 6px;
  }
  .pet-card {
    padding: 4px 12px 4px 5px;
  }
  .level-ring {
    width: 40px;
    height: 40px;
  }
  .level-ring svg {
    width: 40px;
    height: 40px;
  }
  .level-ring span {
    font-size: 16px;
  }
  .pet-name {
    font-size: 15px;
  }
  .pet-xp {
    display: none;
  }
  .round-btn {
    width: 40px;
    height: 40px;
  }
  .top-right {
    gap: 7px;
  }
  .stats {
    grid-template-columns: 1fr 1fr;
    gap: 9px 12px;
    padding: 9px 12px;
    border-radius: 20px;
  }
  .meter-icon {
    width: 26px;
    height: 26px;
  }
  .meter-icon svg {
    width: 15px;
    height: 15px;
  }
  .meter-label {
    font-size: 12px;
    margin-bottom: 3px;
  }
  .meter-bar {
    height: 10px;
  }
  .dock {
    gap: 7px;
    padding: 8px;
    border-radius: 26px;
  }
  .dock-btn {
    width: 72px;
    font-size: 13px;
    padding: 8px 4px 7px;
  }
  .dock-icon svg {
    width: 26px;
    height: 26px;
  }
  .food-card,
  .acc-card {
    width: 92px;
  }
  .food-card img {
    width: 58px;
    height: 58px;
  }
  .tray {
    padding: 10px 8px;
  }
  .tray-cards {
    justify-content: flex-start;
  }
  .facts {
    grid-template-columns: repeat(2, 1fr);
  }
  .bubble-body {
    font-size: 15px;
    padding: 8px 13px;
  }
}

@media (max-height: 560px) and (orientation: landscape) {
  .title {
    font-size: 22px;
  }
  .pet-card {
    display: none;
  }
  .stats {
    padding: 7px 12px;
  }
  .dock-btn {
    width: 74px;
    padding: 6px 4px 6px;
  }
  .dock-btn kbd {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

