  const d = await page.evaluate(() => window.__cowdie.world.debug());
  await page.screenshot({
    path: join(SHOTS, `eat-${food}-${label}.png`),
    clip: { x: Math.max(0, d.head.x - 220), y: Math.max(0, d.head.y - 200), width: 440, height: 400 },
  });
};
await sleep(500);
await grab('a-flying');
await sleep(450);
await grab('b-arrive');
await sleep(500);
await grab('c-chew1');
await sleep(400);
await grab('d-chew2');
await sleep(1500);
await grab('e-later');
await sleep(1800);
await grab('f-swallowed');
console.log('errors', errors);
await browser.close();

